  "rows": [
    [
      {"paragraphs": [{"runs": [{"text": "11:05", "font_family": "Consolas", "font_size": 18, "color": "#1F2933"}]}]},
      {"text": "Normal", "fill": "#EDEFF2", "bold": true},
      {"text": "Database access control change deployed."}
    ],
    [
      {"paragraphs": [{"runs": [{"text": "11:28", "font_family": "Consolas", "font_size": 18, "color": "#1F2933"}]}]},
      {"text": "Critical", "fill": "#F7E4E2", "bold": true},
      {"text": "Deployment reaches customer environments; first errors observed on customer HTTP traffic."}
    ],
    [
      {"paragraphs": [{"runs": [{"text": "11:31", "font_family": "Consolas", "font_size": 18, "color": "#1F2933"}]}]},
      {"text": "Critical", "fill": "#F7E4E2", "bold": true},
      {"paragraphs": ["First automated test detects the issue; manual investigation starts at 11:32 and the", "incident call is created at 11:35."]}
    ],
    [
      {"paragraphs": [{"runs": [{"text": "11:32", "font_family": "Consolas", "font_size": 18, "color": "#1F2933"}]}]},
      {"text": "Critical", "fill": "#F7E4E2", "bold": true},
      {"paragraphs": ["Through 13:05 the team investigates elevated traffic levels and errors to Workers KV. The initial", "symptom appeared to be a degraded Workers KV response rate causing downstream impact on other", "Cloudflare services. Traffic manipulation and account limiting were attempted."]}
    ],
    [
      {"paragraphs": [{"runs": [{"text": "13:05", "font_family": "Consolas", "font_size": 18, "color": "#1F2933"}]}]},
      {"text": "Degraded", "fill": "#FAF0DC", "bold": true},
      {"paragraphs": ["Workers KV and Cloudflare Access bypass implemented and impact reduced: internal system", "bypasses fell back to a prior version of the core proxy."]}
    ]
  ]
}
